-- =============================================================================
-- QR Order - V1__init_schema.sql
-- PostgreSQL 16 | Flyway | PROMPT 02 - Database Design
-- Nguồn nghiệp vụ: "Hệ thống QR Order - SRS & Thiết kế (v0.3)" (§0.1, §0.2, §8,
-- §9.1-9.10, §10, §11.5, §11.6).
--
-- Quy ước:
--   * Tiền: BIGINT, đơn vị VND, không âm. Thời gian: TIMESTAMPTZ.
--   * Enum lưu VARCHAR + CHECK (map @Enumerated(EnumType.STRING) trong JPA).
--   * Tỷ lệ (VAT, phí phục vụ): NUMERIC(5,4) dạng thập phân, 0.0800 = 8%.
--   * Khóa chính: BIGINT GENERATED BY DEFAULT AS IDENTITY.
--   * Tên ràng buộc: pk_, fk_, uq_, ck_; index: ux_ (unique), ix_.
--   * Không xóa cứng dữ liệu nghiệp vụ (BR-A03): trigger chặn DELETE.
--   * File này KHÔNG chứa dữ liệu mẫu: chỉ tạo đúng 1 dòng restaurant_settings
--     với giá trị mặc định đã xác nhận ở SRS §0.2, vat_rate = NULL (BR-P03).
--     Không có tài khoản mặc định (ADMIN đầu tiên do khởi tạo triển khai, BR-A09).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 0. Hàm dùng chung
-- -----------------------------------------------------------------------------

-- BR-A03: chặn xóa cứng dữ liệu nghiệp vụ.
-- Lưu ý: TRUNCATE (dùng dọn dữ liệu trong integration test) không kích hoạt trigger ROW.
CREATE FUNCTION fn_forbid_delete() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'HARD_DELETE_FORBIDDEN: bảng % không cho xóa cứng (BR-A03)', TG_TABLE_NAME
        USING ERRCODE = 'P0001';
END;
$$;

-- Bảng chỉ thêm (append-only): chặn UPDATE và DELETE.
CREATE FUNCTION fn_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'APPEND_ONLY: bảng % chỉ cho phép thêm mới', TG_TABLE_NAME
        USING ERRCODE = 'P0001';
END;
$$;

-- -----------------------------------------------------------------------------
-- 1. Authentication & RBAC (DEC-13 A, BR-A01..A09)
-- -----------------------------------------------------------------------------

CREATE TABLE users (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY,
    username             VARCHAR(50)  NOT NULL,
    password_hash        VARCHAR(255) NOT NULL,
    full_name            VARCHAR(100) NOT NULL,
    role                 VARCHAR(16)  NOT NULL,
    status               VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE',
    last_login_at        TIMESTAMPTZ,
    password_changed_at  TIMESTAMPTZ,
    created_by           BIGINT,
    created_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version              BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT fk_users_created_by FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT ck_users_role CHECK (role IN ('ADMIN', 'MANAGER', 'STAFF', 'KITCHEN')),
    CONSTRAINT ck_users_status CHECK (status IN ('ACTIVE', 'LOCKED', 'DISABLED')),
    CONSTRAINT ck_users_username_format CHECK (username ~ '^[A-Za-z0-9._-]{3,50}$'),
    CONSTRAINT ck_users_full_name_not_blank CHECK (length(btrim(full_name)) > 0)
);
CREATE UNIQUE INDEX ux_users_username_lower ON users (lower(username));
COMMENT ON TABLE users IS 'Tài khoản nhân viên. role là enum, không có bảng roles/user_roles (DEC-13 A). ADMIN hoạt động = role ADMIN và status ACTIVE (BR-A09).';
COMMENT ON COLUMN users.password_hash IS 'BCrypt/Argon2 (NFR-04). Không bao giờ trả ra API hay ghi log.';

-- BR-A09: luôn còn ít nhất một ADMIN hoạt động. Advisory lock tuần tự hóa các thay đổi
-- làm giảm số ADMIN hoạt động; ở READ COMMITTED mỗi câu lệnh trong hàm lấy snapshot mới
-- nên giao dịch thứ hai thấy thay đổi đã commit của giao dịch thứ nhất.
CREATE FUNCTION fn_users_keep_one_active_admin() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.role = 'ADMIN' AND OLD.status = 'ACTIVE'
       AND NOT (NEW.role = 'ADMIN' AND NEW.status = 'ACTIVE') THEN
        PERFORM pg_advisory_xact_lock(hashtext('qr_order.users.active_admin_guard'));
        IF NOT EXISTS (SELECT 1 FROM users
                        WHERE role = 'ADMIN' AND status = 'ACTIVE' AND id <> OLD.id) THEN
            RAISE EXCEPTION 'LAST_ACTIVE_ADMIN: không thể hạ role, khóa hoặc ngừng dùng ADMIN hoạt động cuối cùng (BR-A09)'
                USING ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_users_keep_one_active_admin
    BEFORE UPDATE OF role, status ON users
    FOR EACH ROW EXECUTE FUNCTION fn_users_keep_one_active_admin();

CREATE TABLE user_permission (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY,
    user_id          BIGINT      NOT NULL,
    permission       VARCHAR(32) NOT NULL,
    granted_by       BIGINT      NOT NULL,
    granted_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    reason           TEXT        NOT NULL,
    reauthenticated  BOOLEAN     NOT NULL DEFAULT false,
    revoked_by       BIGINT,
    revoked_at       TIMESTAMPTZ,
    revoke_reason    TEXT,
    CONSTRAINT pk_user_permission PRIMARY KEY (id),
    CONSTRAINT fk_user_permission_user FOREIGN KEY (user_id) REFERENCES users (id),
    CONSTRAINT fk_user_permission_granted_by FOREIGN KEY (granted_by) REFERENCES users (id),
    CONSTRAINT fk_user_permission_revoked_by FOREIGN KEY (revoked_by) REFERENCES users (id),
    CONSTRAINT ck_user_permission_permission CHECK (permission IN (
        'PAYMENT_PROCESS', 'BILL_DISCOUNT', 'BILL_VOID', 'REFUND_RECORD',
        'ITEM_CANCEL_APPROVE', 'SESSION_FORCE_CLOSE', 'SESSION_REOPEN', 'REPORT_VIEW')),
    CONSTRAINT ck_user_permission_reason CHECK (length(btrim(reason)) > 0),
    -- BR-A07: tự cấp cho chính mình bắt buộc xác thực lại.
    CONSTRAINT ck_user_permission_self_grant_reauth CHECK (user_id <> granted_by OR reauthenticated),
    CONSTRAINT ck_user_permission_revoke_fields CHECK (
        (revoked_at IS NULL AND revoked_by IS NULL AND revoke_reason IS NULL)
        OR (revoked_at IS NOT NULL AND revoked_by IS NOT NULL
            AND revoke_reason IS NOT NULL AND length(btrim(revoke_reason)) > 0
            AND revoked_at >= granted_at))
);
-- Mỗi (user, permission) tối đa một bản cấp còn hiệu lực; thu hồi giữ lịch sử (không xóa).
CREATE UNIQUE INDEX ux_user_permission_active ON user_permission (user_id, permission)
    WHERE revoked_at IS NULL;
CREATE INDEX ix_user_permission_user ON user_permission (user_id);
COMMENT ON TABLE user_permission IS 'Permission gắn trực tiếp user (DEC-13 A, BR-A06..A08). Quyền mặc định của MANAGER suy từ role, không lưu dòng. Không dùng để cấp/đổi role ADMIN (BR-A08).';

-- Bản cấp chỉ được cập nhật một lần duy nhất để thu hồi; các cột khác bất biến.
CREATE FUNCTION fn_user_permission_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.revoked_at IS NOT NULL THEN
        RAISE EXCEPTION 'PERMISSION_ALREADY_REVOKED: bản cấp % đã thu hồi', OLD.id USING ERRCODE = 'P0001';
    END IF;
    IF (NEW.user_id, NEW.permission, NEW.granted_by, NEW.granted_at, NEW.reason, NEW.reauthenticated)
       IS DISTINCT FROM
       (OLD.user_id, OLD.permission, OLD.granted_by, OLD.granted_at, OLD.reason, OLD.reauthenticated) THEN
        RAISE EXCEPTION 'PERMISSION_GRANT_IMMUTABLE: chỉ được ghi thông tin thu hồi' USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_user_permission_guard
    BEFORE UPDATE ON user_permission
    FOR EACH ROW EXECUTE FUNCTION fn_user_permission_guard();

-- -----------------------------------------------------------------------------
-- 2. Cấu hình & dãy số
-- -----------------------------------------------------------------------------

CREATE TABLE restaurant_settings (
    id                               SMALLINT     NOT NULL DEFAULT 1,
    timezone                         VARCHAR(64)  NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
    money_rounding_mode              VARCHAR(16)  NOT NULL DEFAULT 'HALF_UP',
    vat_rate                         NUMERIC(5,4),
    prices_include_vat               BOOLEAN      NOT NULL DEFAULT true,
    service_fee_rate                 NUMERIC(5,4) NOT NULL DEFAULT 0,
    service_fee_taxable              BOOLEAN,
    session_idle_timeout_minutes     INTEGER      NOT NULL DEFAULT 180,
    guest_jwt_ttl_minutes            INTEGER      NOT NULL DEFAULT 15,
    batch_claim_ttl_seconds          INTEGER      NOT NULL DEFAULT 60,
    max_pending_batches_per_session  INTEGER      NOT NULL DEFAULT 3,
    join_rate_limit_per_minute       INTEGER      NOT NULL DEFAULT 10,
    order_rate_limit_per_minute      INTEGER      NOT NULL DEFAULT 5,
    max_item_quantity                INTEGER      NOT NULL DEFAULT 99,
    order_confirmation_mode          VARCHAR(20)  NOT NULL DEFAULT 'FIRST_BATCH_ONLY',
    require_table_pin                BOOLEAN      NOT NULL DEFAULT false,
    cleaning_auto_release            BOOLEAN      NOT NULL DEFAULT false,
    updated_by                       BIGINT,
    updated_at                       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version                          BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT pk_restaurant_settings PRIMARY KEY (id),
    CONSTRAINT fk_restaurant_settings_updated_by FOREIGN KEY (updated_by) REFERENCES users (id),
    CONSTRAINT ck_restaurant_settings_single_row CHECK (id = 1),
    -- BR-P01: múi giờ và làm tròn cố định ở giai đoạn 1; đổi cần migration.
    CONSTRAINT ck_restaurant_settings_timezone CHECK (timezone = 'Asia/Ho_Chi_Minh'),
    CONSTRAINT ck_restaurant_settings_rounding CHECK (money_rounding_mode = 'HALF_UP'),
    -- BR-P03: NULL = chưa cấu hình (chặn tạo Bill); khi có thì 0 <= vat_rate < 100%.
    CONSTRAINT ck_restaurant_settings_vat_rate CHECK (vat_rate IS NULL OR (vat_rate >= 0 AND vat_rate < 1)),
    -- DEC-10 A: công thức BR-P02 chỉ định nghĩa cho giá đã gồm VAT.
    CONSTRAINT ck_restaurant_settings_prices_include_vat CHECK (prices_include_vat),
    CONSTRAINT ck_restaurant_settings_service_fee_rate CHECK (service_fee_rate >= 0 AND service_fee_rate < 1),
    -- BR-P04: không cho phí phục vụ > 0 khi service_fee_taxable chưa chốt (P-5).
    CONSTRAINT ck_restaurant_settings_service_fee_taxable CHECK (service_fee_rate = 0 OR service_fee_taxable IS NOT NULL),
    CONSTRAINT ck_restaurant_settings_positive CHECK (
        session_idle_timeout_minutes > 0 AND guest_jwt_ttl_minutes > 0
        AND batch_claim_ttl_seconds > 0 AND max_pending_batches_per_session > 0
        AND join_rate_limit_per_minute > 0 AND order_rate_limit_per_minute > 0
        AND max_item_quantity > 0),
    CONSTRAINT ck_restaurant_settings_confirmation_mode CHECK (order_confirmation_mode IN ('FIRST_BATCH_ONLY', 'ALL', 'NONE'))
);
COMMENT ON TABLE restaurant_settings IS 'Cấu hình nghiệp vụ, đúng 1 dòng (id = 1). Mọi tham số BR-C01. Đổi cấu hình phải ghi audit_log (BR-A05).';
COMMENT ON COLUMN restaurant_settings.vat_rate IS 'NULL = chưa cấu hình; tạo Bill bị chặn với VAT_NOT_CONFIGURED (BR-P03). Không mặc định 0%.';
COMMENT ON COLUMN restaurant_settings.service_fee_taxable IS 'Chưa chốt nghiệp vụ (P-5), giữ NULL.';
COMMENT ON COLUMN restaurant_settings.max_item_quantity IS 'Giới hạn số lượng mỗi dòng món (BR-O03). Mặc định 99 là giả định thiết kế PROMPT 02, chờ xác nhận.';

-- Dòng cấu hình duy nhất với giá trị mặc định đã xác nhận (SRS §0.2). vat_rate để NULL.
INSERT INTO restaurant_settings (id) VALUES (1);

CREATE TABLE daily_sequence (
    sequence_type  VARCHAR(20) NOT NULL,
    business_date  DATE        NOT NULL,
    last_value     INTEGER     NOT NULL,
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_daily_sequence PRIMARY KEY (sequence_type, business_date),
    CONSTRAINT ck_daily_sequence_type CHECK (sequence_type IN ('BILL', 'PAYMENT_RECEIPT', 'REFUND_RECEIPT')),
    -- Định dạng NNNN: tối đa 9999 số mỗi loại mỗi ngày.
    CONSTRAINT ck_daily_sequence_last_value CHECK (last_value BETWEEN 1 AND 9999)
);
COMMENT ON TABLE daily_sequence IS 'Ba dãy số riêng, đánh lại từ 1 mỗi ngày theo Asia/Ho_Chi_Minh, không tái sử dụng (BR-P12). Cấp số qua fn_next_document_number().';

-- Dãy chỉ tăng, không lùi (không tái sử dụng số).
CREATE FUNCTION fn_daily_sequence_monotonic() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.sequence_type <> OLD.sequence_type OR NEW.business_date <> OLD.business_date
       OR NEW.last_value <= OLD.last_value THEN
        RAISE EXCEPTION 'SEQUENCE_NOT_MONOTONIC: dãy % ngày % không được lùi hoặc đổi khóa',
            OLD.sequence_type, OLD.business_date USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_daily_sequence_monotonic
    BEFORE UPDATE ON daily_sequence
    FOR EACH ROW EXECUTE FUNCTION fn_daily_sequence_monotonic();

-- Cấp mã theo BR-P12. Chạy trong transaction của nghiệp vụ: nếu transaction rollback thì
-- số cũng rollback (không bị "tiêu" mất); số đã commit thì không bao giờ cấp lại.
--   BILL            -> BILL-YYYYMMDD-NNNN
--   PAYMENT_RECEIPT -> YYYYMMDD-NNNN
--   REFUND_RECEIPT  -> RF-YYYYMMDD-NNNN
CREATE FUNCTION fn_next_document_number(p_type VARCHAR) RETURNS VARCHAR
LANGUAGE plpgsql AS $$
DECLARE
    v_tz    VARCHAR;
    v_date  DATE;
    v_value INTEGER;
BEGIN
    SELECT timezone INTO v_tz FROM restaurant_settings WHERE id = 1;
    v_date := (now() AT TIME ZONE COALESCE(v_tz, 'Asia/Ho_Chi_Minh'))::date;

    INSERT INTO daily_sequence (sequence_type, business_date, last_value, updated_at)
    VALUES (p_type, v_date, 1, now())
    ON CONFLICT (sequence_type, business_date)
        DO UPDATE SET last_value = daily_sequence.last_value + 1, updated_at = now()
    RETURNING last_value INTO v_value;

    RETURN CASE p_type WHEN 'BILL' THEN 'BILL-' WHEN 'REFUND_RECEIPT' THEN 'RF-' ELSE '' END
           || to_char(v_date, 'YYYYMMDD') || '-' || lpad(v_value::text, 4, '0');
END;
$$;

-- -----------------------------------------------------------------------------
-- 3. Menu (DEC-09 A, FR-CAT-01, FR-PRD-01..04)
-- -----------------------------------------------------------------------------

CREATE TABLE category (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name           VARCHAR(100) NOT NULL,
    description    TEXT,
    display_order  INTEGER      NOT NULL DEFAULT 0,
    is_visible     BOOLEAN      NOT NULL DEFAULT true,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version        BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT pk_category PRIMARY KEY (id),
    CONSTRAINT ck_category_name_not_blank CHECK (length(btrim(name)) > 0)
);
CREATE UNIQUE INDEX ux_category_name_lower ON category (lower(name));
COMMENT ON TABLE category IS 'Danh mục món. Ẩn bằng is_visible, không xóa cứng (BR-A03).';

CREATE TABLE product (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY,
    category_id        BIGINT       NOT NULL,
    name               VARCHAR(150) NOT NULL,
    description        TEXT,
    price              BIGINT       NOT NULL,
    image_url          VARCHAR(500),
    image_public_id    VARCHAR(255),
    status             VARCHAR(16)  NOT NULL DEFAULT 'AVAILABLE',
    display_order      INTEGER      NOT NULL DEFAULT 0,
    status_changed_at  TIMESTAMPTZ,
    status_changed_by  BIGINT,
    created_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version            BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT pk_product PRIMARY KEY (id),
    CONSTRAINT fk_product_category FOREIGN KEY (category_id) REFERENCES category (id),
    CONSTRAINT fk_product_status_changed_by FOREIGN KEY (status_changed_by) REFERENCES users (id),
    CONSTRAINT ck_product_name_not_blank CHECK (length(btrim(name)) > 0),
    CONSTRAINT ck_product_price CHECK (price >= 0),
    CONSTRAINT ck_product_status CHECK (status IN ('AVAILABLE', 'SOLD_OUT', 'HIDDEN')),
    CONSTRAINT ck_product_image_url CHECK (image_url IS NULL OR image_url ~ '^https://')
);
CREATE INDEX ix_product_category_order ON product (category_id, display_order, id);
-- Menu khách (GET /public/menu, NFR-01): bỏ món HIDDEN.
CREATE INDEX ix_product_menu ON product (category_id, display_order) WHERE status <> 'HIDDEN';
COMMENT ON TABLE product IS 'Món. price là giá VND đã gồm VAT (DEC-10 A). SOLD_OUT thủ công, không quản lý tồn kho (DEC-09 A).';
COMMENT ON COLUMN product.image_public_id IS 'public_id Cloudinary để thay/xóa ảnh; image_url là URL https hiển thị.';

CREATE TABLE option_group (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name            VARCHAR(100) NOT NULL,
    selection_type  VARCHAR(16)  NOT NULL,
    is_required     BOOLEAN      NOT NULL DEFAULT false,
    min_select      SMALLINT     NOT NULL DEFAULT 0,
    max_select      SMALLINT,
    is_active       BOOLEAN      NOT NULL DEFAULT true,
    display_order   INTEGER      NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version         BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT pk_option_group PRIMARY KEY (id),
    CONSTRAINT ck_option_group_name_not_blank CHECK (length(btrim(name)) > 0),
    CONSTRAINT ck_option_group_selection_type CHECK (selection_type IN ('SINGLE', 'MULTIPLE')),
    CONSTRAINT ck_option_group_min_select CHECK (min_select >= 0),
    CONSTRAINT ck_option_group_max_select CHECK (max_select IS NULL OR (max_select >= 1 AND max_select >= min_select)),
    -- BR-O03: nhóm chọn 1 tối đa 1 lựa chọn; nhóm bắt buộc phải chọn ít nhất 1.
    CONSTRAINT ck_option_group_single CHECK (selection_type <> 'SINGLE' OR max_select = 1),
    CONSTRAINT ck_option_group_required CHECK (is_required = (min_select >= 1))
);
COMMENT ON TABLE option_group IS 'Nhóm option/topping dùng chung nhiều món (N-N qua product_option_group). FR-PRD-03, BR-O03.';

CREATE TABLE option_item (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY,
    option_group_id  BIGINT       NOT NULL,
    name             VARCHAR(100) NOT NULL,
    extra_price      BIGINT       NOT NULL DEFAULT 0,
    is_active        BOOLEAN      NOT NULL DEFAULT true,
    display_order    INTEGER      NOT NULL DEFAULT 0,
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version          BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT pk_option_item PRIMARY KEY (id),
    CONSTRAINT fk_option_item_group FOREIGN KEY (option_group_id) REFERENCES option_group (id),
    CONSTRAINT ck_option_item_name_not_blank CHECK (length(btrim(name)) > 0),
    CONSTRAINT ck_option_item_extra_price CHECK (extra_price >= 0)
);
CREATE UNIQUE INDEX ux_option_item_group_name_active ON option_item (option_group_id, lower(name)) WHERE is_active;
CREATE INDEX ix_option_item_group ON option_item (option_group_id, display_order);
COMMENT ON COLUMN option_item.extra_price IS 'Phụ thu VND (đã gồm VAT), snapshot vào order_item_option khi đặt.';

CREATE TABLE product_option_group (
    product_id       BIGINT      NOT NULL,
    option_group_id  BIGINT      NOT NULL,
    display_order    INTEGER     NOT NULL DEFAULT 0,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_product_option_group PRIMARY KEY (product_id, option_group_id),
    CONSTRAINT fk_product_option_group_product FOREIGN KEY (product_id) REFERENCES product (id),
    CONSTRAINT fk_product_option_group_group FOREIGN KEY (option_group_id) REFERENCES option_group (id)
);
CREATE INDEX ix_product_option_group_group ON product_option_group (option_group_id);
COMMENT ON TABLE product_option_group IS 'Bảng nối N-N product - option_group. Là cấu hình (không phải dữ liệu giao dịch) nên được phép xóa liên kết; đơn cũ không bị ảnh hưởng nhờ snapshot (BR-O01).';

-- -----------------------------------------------------------------------------
-- 4. Bàn, QR, phiên bàn (DEC-01 A, DEC-04 B, BR-S01..S09)
-- -----------------------------------------------------------------------------

CREATE TABLE dining_table (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY,
    code               VARCHAR(20)  NOT NULL,
    display_name       VARCHAR(50)  NOT NULL,
    area               VARCHAR(50),
    capacity           SMALLINT     NOT NULL,
    status             VARCHAR(20)  NOT NULL DEFAULT 'AVAILABLE',
    is_active          BOOLEAN      NOT NULL DEFAULT true,
    display_order      INTEGER      NOT NULL DEFAULT 0,
    status_changed_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    created_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version            BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT pk_dining_table PRIMARY KEY (id),
    CONSTRAINT ck_dining_table_code CHECK (code ~ '^[A-Za-z0-9_-]{1,20}$'),
    CONSTRAINT ck_dining_table_display_name CHECK (length(btrim(display_name)) > 0),
    CONSTRAINT ck_dining_table_capacity CHECK (capacity BETWEEN 1 AND 100),
    CONSTRAINT ck_dining_table_status CHECK (status IN ('AVAILABLE', 'OCCUPIED', 'PAYMENT_PENDING', 'CLEANING')),
    -- BR-S08, §9.5: chỉ ngừng dùng khi bàn AVAILABLE.
    CONSTRAINT ck_dining_table_inactive_only_available CHECK (is_active OR status = 'AVAILABLE')
);
CREATE UNIQUE INDEX ux_dining_table_code_lower ON dining_table (lower(code));
-- Sơ đồ bàn (FR-TBL-02).
CREATE INDEX ix_dining_table_floor_plan ON dining_table (area, display_order, id) WHERE is_active;
COMMENT ON TABLE dining_table IS 'Bàn: 4 trạng thái + cờ is_active tách rời (DEC-04 B). status là cột denormalized, cập nhật cùng transaction với phiên (BR-S08, §9.7).';

CREATE TABLE qr_code (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY,
    table_id             BIGINT      NOT NULL,
    token_hash           CHAR(64)    NOT NULL,
    status               VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
    created_by           BIGINT,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    deactivated_by       BIGINT,
    deactivated_at       TIMESTAMPTZ,
    deactivation_reason  TEXT,
    CONSTRAINT pk_qr_code PRIMARY KEY (id),
    CONSTRAINT fk_qr_code_table FOREIGN KEY (table_id) REFERENCES dining_table (id),
    CONSTRAINT fk_qr_code_created_by FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT fk_qr_code_deactivated_by FOREIGN KEY (deactivated_by) REFERENCES users (id),
    CONSTRAINT uq_qr_code_token_hash UNIQUE (token_hash),
    -- SHA-256 hex của qrToken (>= 128 bit ngẫu nhiên). Không lưu token gốc (BR-S05).
    CONSTRAINT ck_qr_code_token_hash CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_qr_code_status CHECK (status IN ('ACTIVE', 'ROTATED', 'REVOKED')),
    CONSTRAINT ck_qr_code_deactivation CHECK ((status = 'ACTIVE') = (deactivated_at IS NULL))
);
-- Tối đa 1 QR ACTIVE mỗi bàn (BR-S05, §11.5).
CREATE UNIQUE INDEX ux_qr_code_active_per_table ON qr_code (table_id) WHERE status = 'ACTIVE';
CREATE INDEX ix_qr_code_table ON qr_code (table_id, created_at);
COMMENT ON TABLE qr_code IS 'QR bàn. Chỉ lưu token_hash; xoay vòng = ROTATED + tạo dòng mới; thu hồi = REVOKED (BR-S05). Tra cứu khi join: WHERE token_hash = ? AND status = ''ACTIVE''.';

CREATE TABLE table_session (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    table_id            BIGINT      NOT NULL,
    status              VARCHAR(16) NOT NULL DEFAULT 'OPEN',
    opened_by_type      VARCHAR(8)  NOT NULL,
    opened_by_user_id   BIGINT,
    opened_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_activity_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    verified_at         TIMESTAMPTZ,
    table_pin           CHAR(4),
    needs_attention     BOOLEAN     NOT NULL DEFAULT false,
    attention_reason    VARCHAR(32),
    attention_set_at    TIMESTAMPTZ,
    billing_started_at  TIMESTAMPTZ,
    closed_at           TIMESTAMPTZ,
    closed_by           BIGINT,
    close_reason        TEXT,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    version             BIGINT      NOT NULL DEFAULT 0,
    CONSTRAINT pk_table_session PRIMARY KEY (id),
    CONSTRAINT fk_table_session_table FOREIGN KEY (table_id) REFERENCES dining_table (id),
    CONSTRAINT fk_table_session_opened_by FOREIGN KEY (opened_by_user_id) REFERENCES users (id),
    CONSTRAINT fk_table_session_closed_by FOREIGN KEY (closed_by) REFERENCES users (id),
    CONSTRAINT ck_table_session_status CHECK (status IN ('OPEN', 'BILLING', 'CLOSED', 'EXPIRED', 'FORCE_CLOSED')),
    CONSTRAINT ck_table_session_opened_by CHECK (
        opened_by_type IN ('GUEST', 'STAFF') AND ((opened_by_type = 'STAFF') = (opened_by_user_id IS NOT NULL))),
    CONSTRAINT ck_table_session_pin CHECK (table_pin IS NULL OR table_pin ~ '^[0-9]{4}$'),
    -- BR-S07: needs_attention của phiên chỉ dùng cho phiên idle còn đơn chưa thanh toán.
    CONSTRAINT ck_table_session_attention CHECK (
        (NOT needs_attention AND attention_reason IS NULL AND attention_set_at IS NULL)
        OR (needs_attention AND attention_reason = 'IDLE_WITH_UNPAID_ORDER'
            AND attention_set_at IS NOT NULL AND status IN ('OPEN', 'BILLING'))),
    CONSTRAINT ck_table_session_closed_at CHECK (
        (status IN ('CLOSED', 'EXPIRED', 'FORCE_CLOSED')) = (closed_at IS NOT NULL)),
    -- BR-S06: force-close bắt buộc người thực hiện và lý do.
    CONSTRAINT ck_table_session_force_close CHECK (
        status <> 'FORCE_CLOSED' OR (closed_by IS NOT NULL AND close_reason IS NOT NULL AND length(btrim(close_reason)) > 0)),
    CONSTRAINT ck_table_session_time_order CHECK (closed_at IS NULL OR closed_at >= opened_at)
);
-- BR-S01, §7.1: tối đa 1 phiên OPEN/BILLING mỗi bàn.
CREATE UNIQUE INDEX ux_table_session_active_per_table ON table_session (table_id) WHERE status IN ('OPEN', 'BILLING');
CREATE INDEX ix_table_session_table_opened ON table_session (table_id, opened_at DESC);
-- Scheduler EXPIRED / needs_attention (BR-S07, UC36).
CREATE INDEX ix_table_session_idle_scan ON table_session (last_activity_at) WHERE status = 'OPEN';
-- Danh sách "Cần xử lý" (FR-SES-06).
CREATE INDEX ix_table_session_needs_attention ON table_session (attention_set_at) WHERE needs_attention;
COMMENT ON TABLE table_session IS 'Phiên bàn. CLOSED/EXPIRED/FORCE_CLOSED là trạng thái cuối, phiên mới luôn là dòng mới (§9.6).';
COMMENT ON COLUMN table_session.verified_at IS 'Thời điểm phiên có đợt ACCEPTED/PARTIALLY_ACCEPTED đầu tiên (BR-S04, FIRST_BATCH_ONLY).';
COMMENT ON COLUMN table_session.table_pin IS 'PIN 4 số tùy chọn (require_table_pin, DEC-07 A); nhân viên đọc để cấp cho khách nên lưu dạng rõ.';

CREATE TABLE session_device (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY,
    session_id       BIGINT      NOT NULL,
    device_id        VARCHAR(64) NOT NULL,
    joined_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    pin_verified_at  TIMESTAMPTZ,
    CONSTRAINT pk_session_device PRIMARY KEY (id),
    CONSTRAINT fk_session_device_session FOREIGN KEY (session_id) REFERENCES table_session (id),
    CONSTRAINT uq_session_device_session_device UNIQUE (session_id, device_id),
    CONSTRAINT ck_session_device_device_id CHECK (device_id ~ '^[A-Za-z0-9_-]{8,64}$')
);
COMMENT ON TABLE session_device IS 'Nhiều thiết bị chung một phiên (FR-SES-01, §7.1). device_id do client sinh (UUID).';

CREATE TABLE service_call (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY,
    session_id            BIGINT      NOT NULL,
    type                  VARCHAR(20) NOT NULL,
    status                VARCHAR(16) NOT NULL DEFAULT 'OPEN',
    created_by_type       VARCHAR(8)  NOT NULL,
    created_by_device_id  VARCHAR(64),
    created_by_user_id    BIGINT,
    note                  TEXT,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    acknowledged_by       BIGINT,
    acknowledged_at       TIMESTAMPTZ,
    resolved_by           BIGINT,
    resolved_at           TIMESTAMPTZ,
    resolution_note       TEXT,
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    version               BIGINT      NOT NULL DEFAULT 0,
    CONSTRAINT pk_service_call PRIMARY KEY (id),
    CONSTRAINT fk_service_call_session FOREIGN KEY (session_id) REFERENCES table_session (id),
    CONSTRAINT fk_service_call_created_by FOREIGN KEY (created_by_user_id) REFERENCES users (id),
    CONSTRAINT fk_service_call_acknowledged_by FOREIGN KEY (acknowledged_by) REFERENCES users (id),
    CONSTRAINT fk_service_call_resolved_by FOREIGN KEY (resolved_by) REFERENCES users (id),
    CONSTRAINT ck_service_call_type CHECK (type IN ('CALL_STAFF', 'REQUEST_PAYMENT', 'MANAGER_SUPPORT')),
    CONSTRAINT ck_service_call_status CHECK (status IN ('OPEN', 'ACKNOWLEDGED', 'RESOLVED')),
    -- §9.8, §10: CALL_STAFF/REQUEST_PAYMENT do khách tạo; MANAGER_SUPPORT do Staff tạo.
    CONSTRAINT ck_service_call_creator CHECK (
        (created_by_type = 'GUEST' AND type IN ('CALL_STAFF', 'REQUEST_PAYMENT')
            AND created_by_device_id IS NOT NULL AND created_by_user_id IS NULL)
        OR (created_by_type = 'STAFF' AND type = 'MANAGER_SUPPORT' AND created_by_user_id IS NOT NULL)),
    -- resolved_by NULL = hệ thống tự RESOLVED (ví dụ REQUEST_PAYMENT khi tạo Bill).
    CONSTRAINT ck_service_call_lifecycle CHECK (
        (status = 'OPEN' AND acknowledged_at IS NULL AND resolved_at IS NULL)
        OR (status = 'ACKNOWLEDGED' AND acknowledged_at IS NOT NULL AND acknowledged_by IS NOT NULL AND resolved_at IS NULL)
        OR (status = 'RESOLVED' AND resolved_at IS NOT NULL))
);
-- FR-NOT-03, §9.8: tối đa 1 yêu cầu đang mở mỗi (phiên, loại).
CREATE UNIQUE INDEX ux_service_call_open_per_type ON service_call (session_id, type) WHERE status IN ('OPEN', 'ACKNOWLEDGED');
-- Danh sách "Cần xử lý" của Staff/Manager.
CREATE INDEX ix_service_call_open_queue ON service_call (created_at) WHERE status IN ('OPEN', 'ACKNOWLEDGED');
CREATE INDEX ix_service_call_session ON service_call (session_id, created_at);

-- -----------------------------------------------------------------------------
-- 5. Đặt món & bếp (DEC-02 A, DEC-06 A, DEC-12 B, BR-O01..O13)
-- -----------------------------------------------------------------------------

CREATE TABLE orders (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    session_id          BIGINT      NOT NULL,
    status              VARCHAR(16) NOT NULL DEFAULT 'OPEN',
    status_before_void  VARCHAR(16),
    needs_attention     BOOLEAN     NOT NULL DEFAULT false,
    attention_reason    VARCHAR(32),
    attention_set_at    TIMESTAMPTZ,
    shortfall_amount    BIGINT,
    writeoff_reason     TEXT,
    written_off_by      BIGINT,
    written_off_at      TIMESTAMPTZ,
    paid_at             TIMESTAMPTZ,
    voided_at           TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    version             BIGINT      NOT NULL DEFAULT 0,
    CONSTRAINT pk_orders PRIMARY KEY (id),
    CONSTRAINT fk_orders_session FOREIGN KEY (session_id) REFERENCES table_session (id),
    CONSTRAINT fk_orders_written_off_by FOREIGN KEY (written_off_by) REFERENCES users (id),
    -- DEC-02 A: Session 1-1 Order.
    CONSTRAINT uq_orders_session UNIQUE (session_id),
    -- Phục vụ FK kép từ order_batch (đảm bảo batch.session_id khớp order).
    CONSTRAINT uq_orders_id_session UNIQUE (id, session_id),
    CONSTRAINT ck_orders_status CHECK (status IN ('OPEN', 'LOCKED', 'PAID', 'VOIDED', 'WRITTEN_OFF')),
    CONSTRAINT ck_orders_status_before_void CHECK (status_before_void IS NULL OR status_before_void IN ('LOCKED', 'PAID')),
    -- BR-P17: cờ thuộc Order, chỉ khi LOCKED chờ Bill thay thế.
    CONSTRAINT ck_orders_attention CHECK (
        (NOT needs_attention AND attention_reason IS NULL AND attention_set_at IS NULL)
        OR (needs_attention AND attention_reason = 'AWAITING_REPLACEMENT_BILL'
            AND attention_set_at IS NOT NULL AND status = 'LOCKED')),
    -- BR-P15, BR-P18: WRITTEN_OFF luôn có thất thu > 0, lý do, người và thời điểm.
    CONSTRAINT ck_orders_writeoff CHECK (
        (status = 'WRITTEN_OFF' AND shortfall_amount IS NOT NULL AND shortfall_amount > 0
            AND writeoff_reason IS NOT NULL AND length(btrim(writeoff_reason)) > 0
            AND written_off_by IS NOT NULL AND written_off_at IS NOT NULL)
        OR (status <> 'WRITTEN_OFF' AND shortfall_amount IS NULL AND writeoff_reason IS NULL
            AND written_off_by IS NULL AND written_off_at IS NULL)),
    CONSTRAINT ck_orders_voided_at CHECK ((status = 'VOIDED') = (voided_at IS NOT NULL)),
    CONSTRAINT ck_orders_paid_at CHECK (status <> 'PAID' OR paid_at IS NOT NULL)
);
-- Danh sách "Cần xử lý": Order chờ Bill thay thế (BR-P17, FR-PAY-13).
CREATE INDEX ix_orders_needs_attention ON orders (attention_set_at) WHERE needs_attention;
-- Báo cáo thất thu (FR-RPT-01/02): doanh thu không gồm shortfall.
CREATE INDEX ix_orders_written_off_report ON orders (written_off_at) INCLUDE (shortfall_amount) WHERE status = 'WRITTEN_OFF';
COMMENT ON TABLE orders IS 'Order của phiên (1-1). Thất thu lưu ở Order, kể cả khi chưa có Bill (BR-P15). VOIDED/WRITTEN_OFF là trạng thái cuối.';
COMMENT ON COLUMN orders.status_before_void IS 'Trạng thái Order trước khi Manager yêu cầu Void, để rút Void trả về đúng trạng thái (BR-P14).';
COMMENT ON COLUMN orders.shortfall_amount IS 'Thất thu VND = Total - net_collected khi WRITTEN_OFF; không bao giờ tính vào doanh thu.';

CREATE TABLE order_batch (
    id                     BIGINT GENERATED BY DEFAULT AS IDENTITY,
    order_id               BIGINT      NOT NULL,
    session_id             BIGINT      NOT NULL,
    seq                    INTEGER     NOT NULL,
    client_request_id      UUID        NOT NULL,
    status                 VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    requires_confirmation  BOOLEAN     NOT NULL,
    submitted_by_type      VARCHAR(8)  NOT NULL,
    device_id              VARCHAR(64),
    submitted_by_user_id   BIGINT,
    submitted_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    claimed_by             BIGINT,
    claimed_at             TIMESTAMPTZ,
    decided_by             BIGINT,
    decided_at             TIMESTAMPTZ,
    reason_code            VARCHAR(50),
    reason_note            TEXT,
    completed_at           TIMESTAMPTZ,
    updated_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    version                BIGINT      NOT NULL DEFAULT 0,
    CONSTRAINT pk_order_batch PRIMARY KEY (id),
    CONSTRAINT fk_order_batch_order_session FOREIGN KEY (order_id, session_id) REFERENCES orders (id, session_id),
    CONSTRAINT fk_order_batch_submitted_by FOREIGN KEY (submitted_by_user_id) REFERENCES users (id),
    CONSTRAINT fk_order_batch_claimed_by FOREIGN KEY (claimed_by) REFERENCES users (id),
    CONSTRAINT fk_order_batch_decided_by FOREIGN KEY (decided_by) REFERENCES users (id),
    -- BR-O04, §7.7: idempotent theo clientRequestId.
    CONSTRAINT uq_order_batch_session_client_request UNIQUE (session_id, client_request_id),
    CONSTRAINT uq_order_batch_order_seq UNIQUE (order_id, seq),
    CONSTRAINT uq_order_batch_id_order UNIQUE (id, order_id),
    CONSTRAINT ck_order_batch_seq CHECK (seq >= 1),
    CONSTRAINT ck_order_batch_status CHECK (status IN (
        'PENDING', 'ACCEPTED', 'PARTIALLY_ACCEPTED', 'REJECTED', 'CANCELLED', 'COMPLETED')),
    CONSTRAINT ck_order_batch_submitter CHECK (
        (submitted_by_type = 'GUEST' AND device_id IS NOT NULL AND submitted_by_user_id IS NULL)
        OR (submitted_by_type = 'STAFF' AND submitted_by_user_id IS NOT NULL)),
    -- BR-O10: claim gồm người và thời điểm (TTL tính từ claimed_at).
    CONSTRAINT ck_order_batch_claim CHECK ((claimed_by IS NULL) = (claimed_at IS NULL)),
    CONSTRAINT ck_order_batch_decided CHECK ((decided_by IS NULL) OR (decided_at IS NOT NULL)),
    -- BR-O08: từ chối cả đợt phải có lý do.
    CONSTRAINT ck_order_batch_reject_reason CHECK (status <> 'REJECTED' OR reason_code IS NOT NULL),
    CONSTRAINT ck_order_batch_reason_code CHECK (reason_code IS NULL OR reason_code ~ '^[A-Z][A-Z0-9_]{1,49}$'),
    CONSTRAINT ck_order_batch_completed_at CHECK (status <> 'COMPLETED' OR completed_at IS NOT NULL)
);
-- Hàng đợi đợt chờ xác nhận của Staff (§3.3, NFR-01).
CREATE INDEX ix_order_batch_pending_queue ON order_batch (submitted_at) WHERE status = 'PENDING';
-- Đếm đợt PENDING của phiên (BR-S09) và kiểm tra BR-O11 trước khi tạo Bill.
CREATE INDEX ix_order_batch_pending_by_session ON order_batch (session_id) WHERE status = 'PENDING';
COMMENT ON TABLE order_batch IS 'Mỗi lần gửi là một đợt (BR-O04). Claim: UPDATE có điều kiện theo claimed_by/claimed_at và TTL batch_claim_ttl_seconds (BR-O10).';

CREATE TABLE order_item (
    id                     BIGINT GENERATED BY DEFAULT AS IDENTITY,
    order_id               BIGINT       NOT NULL,
    batch_id               BIGINT       NOT NULL,
    product_id             BIGINT       NOT NULL,
    product_name           VARCHAR(150) NOT NULL,
    unit_price             BIGINT       NOT NULL,
    option_extra_per_unit  BIGINT       NOT NULL DEFAULT 0,
    quantity               INTEGER      NOT NULL,
    line_total             BIGINT       NOT NULL,
    note                   VARCHAR(500),
    status                 VARCHAR(16)  NOT NULL DEFAULT 'PENDING',
    reason_code            VARCHAR(50),
    reason_note            TEXT,
    wasted                 BOOLEAN      NOT NULL DEFAULT false,
    device_id              VARCHAR(64),
    created_by_user_id     BIGINT,
    created_at             TIMESTAMPTZ  NOT NULL DEFAULT now(),
    confirmed_at           TIMESTAMPTZ,
    preparing_at           TIMESTAMPTZ,
    ready_at               TIMESTAMPTZ,
    served_at              TIMESTAMPTZ,
    closed_at              TIMESTAMPTZ,
    status_changed_by      BIGINT,
    updated_at             TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version                BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT pk_order_item PRIMARY KEY (id),
    CONSTRAINT fk_order_item_batch_order FOREIGN KEY (batch_id, order_id) REFERENCES order_batch (id, order_id),
    CONSTRAINT fk_order_item_product FOREIGN KEY (product_id) REFERENCES product (id),
    CONSTRAINT fk_order_item_created_by FOREIGN KEY (created_by_user_id) REFERENCES users (id),
    CONSTRAINT fk_order_item_status_changed_by FOREIGN KEY (status_changed_by) REFERENCES users (id),
    CONSTRAINT ck_order_item_status CHECK (status IN (
        'PENDING', 'CONFIRMED', 'PREPARING', 'READY', 'SERVED', 'CANCELLED', 'REJECTED')),
    CONSTRAINT ck_order_item_money CHECK (unit_price >= 0 AND option_extra_per_unit >= 0 AND line_total >= 0),
    CONSTRAINT ck_order_item_quantity CHECK (quantity >= 1),
    -- BR-P02: thành tiền dòng = (đơn giá + phụ thu option) x số lượng.
    CONSTRAINT ck_order_item_line_total CHECK (line_total = (unit_price + option_extra_per_unit) * quantity),
    -- BR-O08: hủy/từ chối bắt buộc reasonCode.
    CONSTRAINT ck_order_item_reason CHECK ((status IN ('CANCELLED', 'REJECTED')) = (reason_code IS NOT NULL)),
    CONSTRAINT ck_order_item_reason_code CHECK (reason_code IS NULL OR reason_code ~ '^[A-Z][A-Z0-9_]{1,49}$'),
    -- BR-O06: wasted chỉ với món đã hủy/từ chối.
    CONSTRAINT ck_order_item_wasted CHECK (NOT wasted OR status IN ('CANCELLED', 'REJECTED')),
    CONSTRAINT ck_order_item_orderer CHECK (device_id IS NOT NULL OR created_by_user_id IS NOT NULL),
    CONSTRAINT ck_order_item_closed_at CHECK ((status IN ('CANCELLED', 'REJECTED')) = (closed_at IS NOT NULL)),
    CONSTRAINT ck_order_item_milestones CHECK (
        (status NOT IN ('CONFIRMED', 'PREPARING', 'READY', 'SERVED') OR confirmed_at IS NOT NULL)
        AND (status NOT IN ('PREPARING', 'READY', 'SERVED') OR preparing_at IS NOT NULL)
        AND (status NOT IN ('READY', 'SERVED') OR ready_at IS NOT NULL)
        AND (status <> 'SERVED' OR served_at IS NOT NULL))
);
CREATE INDEX ix_order_item_order ON order_item (order_id, status);
CREATE INDEX ix_order_item_batch ON order_item (batch_id);
-- KDS: món CONFIRMED/PREPARING theo thời gian (FR-KIT-01, NFR-01).
CREATE INDEX ix_order_item_kds ON order_item (status, confirmed_at) WHERE status IN ('CONFIRMED', 'PREPARING');
-- Món READY chờ mang ra (/topic/staff/ready).
CREATE INDEX ix_order_item_ready ON order_item (ready_at) WHERE status = 'READY';
-- BR-O13: đổi SOLD_OUT tìm nhanh item PENDING/CONFIRMED của món.
CREATE INDEX ix_order_item_product_open ON order_item (product_id) WHERE status IN ('PENDING', 'CONFIRMED');
-- Báo cáo top món, tỷ lệ hủy/từ chối, wasted (FR-RPT-02).
CREATE INDEX ix_order_item_product_report ON order_item (product_id, created_at);
CREATE INDEX ix_order_item_wasted_report ON order_item (closed_at) WHERE wasted;
COMMENT ON TABLE order_item IS 'Dòng món. Tên và giá là snapshot (BR-O01). Món tính tiền = CONFIRMED, PREPARING, READY, SERVED (BR-P18).';
COMMENT ON COLUMN order_item.option_extra_per_unit IS 'Tổng phụ thu option cho 1 đơn vị = SUM(order_item_option.extra_price), snapshot.';

CREATE TABLE order_item_option (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY,
    order_item_id    BIGINT       NOT NULL,
    option_group_id  BIGINT       NOT NULL,
    option_item_id   BIGINT       NOT NULL,
    group_name       VARCHAR(100) NOT NULL,
    option_name      VARCHAR(100) NOT NULL,
    extra_price      BIGINT       NOT NULL,
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_order_item_option PRIMARY KEY (id),
    CONSTRAINT fk_order_item_option_item FOREIGN KEY (order_item_id) REFERENCES order_item (id),
    CONSTRAINT fk_order_item_option_group_ref FOREIGN KEY (option_group_id) REFERENCES option_group (id),
    CONSTRAINT fk_order_item_option_item_ref FOREIGN KEY (option_item_id) REFERENCES option_item (id),
    CONSTRAINT uq_order_item_option UNIQUE (order_item_id, option_item_id),
    CONSTRAINT ck_order_item_option_extra_price CHECK (extra_price >= 0)
);
COMMENT ON TABLE order_item_option IS 'Snapshot option tại thời điểm đặt (DEC-12 B, BR-O01). Chỉ thêm, không sửa.';

CREATE TABLE item_cancel_request (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY,
    order_item_id           BIGINT      NOT NULL,
    status                  VARCHAR(16) NOT NULL DEFAULT 'PENDING',
    item_status_at_request  VARCHAR(16) NOT NULL,
    requested_by_type       VARCHAR(8)  NOT NULL,
    requested_by_device_id  VARCHAR(64),
    requested_by_user_id    BIGINT,
    request_reason          TEXT,
    requested_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    decided_by              BIGINT,
    decided_at              TIMESTAMPTZ,
    decision_reason         TEXT,
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    version                 BIGINT      NOT NULL DEFAULT 0,
    CONSTRAINT pk_item_cancel_request PRIMARY KEY (id),
    CONSTRAINT fk_item_cancel_request_item FOREIGN KEY (order_item_id) REFERENCES order_item (id),
    CONSTRAINT fk_item_cancel_request_requested_by FOREIGN KEY (requested_by_user_id) REFERENCES users (id),
    CONSTRAINT fk_item_cancel_request_decided_by FOREIGN KEY (decided_by) REFERENCES users (id),
    CONSTRAINT ck_item_cancel_request_status CHECK (status IN ('PENDING', 'APPROVED', 'DENIED')),
    -- BR-O06: chỉ cho món PREPARING hoặc READY.
    CONSTRAINT ck_item_cancel_request_item_status CHECK (item_status_at_request IN ('PREPARING', 'READY')),
    CONSTRAINT ck_item_cancel_request_requester CHECK (
        (requested_by_type = 'GUEST' AND requested_by_device_id IS NOT NULL AND requested_by_user_id IS NULL)
        OR (requested_by_type = 'STAFF' AND requested_by_user_id IS NOT NULL)),
    CONSTRAINT ck_item_cancel_request_decision CHECK (
        (status = 'PENDING' AND decided_by IS NULL AND decided_at IS NULL)
        OR (status IN ('APPROVED', 'DENIED') AND decided_by IS NOT NULL AND decided_at IS NOT NULL)),
    CONSTRAINT ck_item_cancel_request_deny_reason CHECK (
        status <> 'DENIED' OR (decision_reason IS NOT NULL AND length(btrim(decision_reason)) > 0))
);
-- Một yêu cầu PENDING mỗi món.
CREATE UNIQUE INDEX ux_item_cancel_request_pending ON item_cancel_request (order_item_id) WHERE status = 'PENDING';
CREATE INDEX ix_item_cancel_request_item ON item_cancel_request (order_item_id);
-- Danh sách chờ Manager duyệt.
CREATE INDEX ix_item_cancel_request_pending_queue ON item_cancel_request (requested_at) WHERE status = 'PENDING';

-- -----------------------------------------------------------------------------
-- 6. Thanh toán, hóa đơn, hoàn tiền (O1, P1..P4, BR-P01..P18)
-- -----------------------------------------------------------------------------

CREATE TABLE bill (
    id                     BIGINT GENERATED BY DEFAULT AS IDENTITY,
    order_id               BIGINT       NOT NULL,
    bill_number            VARCHAR(18)  NOT NULL,
    status                 VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE',
    payment_status         VARCHAR(16)  NOT NULL DEFAULT 'UNPAID',
    subtotal_amount        BIGINT       NOT NULL,
    discount_amount        BIGINT       NOT NULL DEFAULT 0,
    discount_reason        TEXT,
    discounted_by          BIGINT,
    net_amount             BIGINT       NOT NULL,
    service_fee_rate       NUMERIC(5,4) NOT NULL,
    service_fee_taxable    BOOLEAN,
    service_fee_amount     BIGINT       NOT NULL,
    total_amount           BIGINT       NOT NULL,
    vat_rate               NUMERIC(5,4) NOT NULL,
    vat_amount             BIGINT       NOT NULL,
    replaces_bill_id       BIGINT,
    created_by             BIGINT       NOT NULL,
    created_at             TIMESTAMPTZ  NOT NULL DEFAULT now(),
    paid_at                TIMESTAMPTZ,
    void_type              VARCHAR(32),
    void_requested_by      BIGINT,
    void_requested_at      TIMESTAMPTZ,
    void_reason            TEXT,
    voided_by              BIGINT,
    voided_at              TIMESTAMPTZ,
    void_withdrawn_by      BIGINT,
    void_withdrawn_at      TIMESTAMPTZ,
    void_withdraw_reason   TEXT,
    written_off_at         TIMESTAMPTZ,
    updated_at             TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version                BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT pk_bill PRIMARY KEY (id),
    CONSTRAINT fk_bill_order FOREIGN KEY (order_id) REFERENCES orders (id),
    CONSTRAINT uq_bill_number UNIQUE (bill_number),
    CONSTRAINT uq_bill_id_order UNIQUE (id, order_id),
    -- Bill thay thế phải thuộc cùng Order với Bill bị thay (BR-P16).
    CONSTRAINT fk_bill_replaces FOREIGN KEY (replaces_bill_id, order_id) REFERENCES bill (id, order_id),
    CONSTRAINT fk_bill_created_by FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT fk_bill_discounted_by FOREIGN KEY (discounted_by) REFERENCES users (id),
    CONSTRAINT fk_bill_void_requested_by FOREIGN KEY (void_requested_by) REFERENCES users (id),
    CONSTRAINT fk_bill_voided_by FOREIGN KEY (voided_by) REFERENCES users (id),
    CONSTRAINT fk_bill_void_withdrawn_by FOREIGN KEY (void_withdrawn_by) REFERENCES users (id),
    CONSTRAINT ck_bill_number_format CHECK (bill_number ~ '^BILL-[0-9]{8}-[0-9]{4}$'),
    CONSTRAINT ck_bill_status CHECK (status IN ('ACTIVE', 'VOID_PENDING', 'VOIDED', 'WRITTEN_OFF')),
    CONSTRAINT ck_bill_payment_status CHECK (payment_status IN ('UNPAID', 'PARTIALLY_PAID', 'PAID')),
    CONSTRAINT ck_bill_amounts_non_negative CHECK (
        subtotal_amount >= 0 AND discount_amount >= 0 AND net_amount >= 0
        AND service_fee_amount >= 0 AND total_amount >= 0 AND vat_amount >= 0),
    -- BR-P07: giảm giá không vượt Subtotal; có giảm giá thì bắt buộc lý do và người nhập.
    CONSTRAINT ck_bill_discount_limit CHECK (discount_amount <= subtotal_amount),
    CONSTRAINT ck_bill_discount_reason CHECK (
        discount_amount = 0 OR (discount_reason IS NOT NULL AND length(btrim(discount_reason)) > 0 AND discounted_by IS NOT NULL)),
    -- BR-P02: Net = Subtotal - Discount.
    CONSTRAINT ck_bill_net CHECK (net_amount = subtotal_amount - discount_amount),
    CONSTRAINT ck_bill_service_fee_rate CHECK (service_fee_rate >= 0 AND service_fee_rate < 1),
    CONSTRAINT ck_bill_service_fee_taxable CHECK (service_fee_rate = 0 OR service_fee_taxable IS NOT NULL),
    -- BR-P02, BR-P01: ServiceFee = round(Net x s), HALF_UP (round(numeric) của PostgreSQL làm tròn
    -- nửa ra xa 0, trùng HALF_UP với số không âm).
    CONSTRAINT ck_bill_service_fee CHECK (service_fee_amount = round(net_amount * service_fee_rate)),
    -- BR-P02: Total = Net + ServiceFee (VAT đã nằm trong giá, không cộng thêm).
    CONSTRAINT ck_bill_total CHECK (total_amount = net_amount + service_fee_amount),
    -- BR-P03: Bill luôn có vat_rate hợp lệ (snapshot).
    CONSTRAINT ck_bill_vat_rate CHECK (vat_rate >= 0 AND vat_rate < 1),
    -- BR-P02: VAT = round(TaxBase x r / (1 + r)), TaxBase = Net (+ ServiceFee nếu chịu thuế).
    CONSTRAINT ck_bill_vat_amount CHECK (vat_amount = round(
        (net_amount + CASE WHEN COALESCE(service_fee_taxable, false) THEN service_fee_amount ELSE 0 END)
        * vat_rate / (1 + vat_rate))),
    CONSTRAINT ck_bill_replaces_self CHECK (replaces_bill_id IS NULL OR replaces_bill_id <> id),
    CONSTRAINT ck_bill_paid_at CHECK (payment_status <> 'PAID' OR paid_at IS NOT NULL),
    CONSTRAINT ck_bill_void_type CHECK (void_type IS NULL OR void_type IN ('SESSION_REOPEN', 'MANAGER_VOID', 'FORCE_CLOSE_NO_CHARGE')),
    -- BR-P09: yêu cầu Void có người, thời điểm, lý do.
    CONSTRAINT ck_bill_void_pending CHECK (
        status <> 'VOID_PENDING' OR (void_requested_by IS NOT NULL AND void_requested_at IS NOT NULL
            AND void_reason IS NOT NULL AND length(btrim(void_reason)) > 0)),
    CONSTRAINT ck_bill_voided CHECK ((status = 'VOIDED') = (voided_at IS NOT NULL AND void_type IS NOT NULL)),
    CONSTRAINT ck_bill_manager_void_reason CHECK (
        void_type IS DISTINCT FROM 'MANAGER_VOID' OR (void_reason IS NOT NULL AND length(btrim(void_reason)) > 0)),
    CONSTRAINT ck_bill_void_withdrawn CHECK (
        (void_withdrawn_at IS NULL AND void_withdrawn_by IS NULL AND void_withdraw_reason IS NULL)
        OR (void_withdrawn_at IS NOT NULL AND void_withdrawn_by IS NOT NULL
            AND void_withdraw_reason IS NOT NULL AND length(btrim(void_withdraw_reason)) > 0)),
    -- BR-P15: WRITTEN_OFF không bao giờ PAID.
    CONSTRAINT ck_bill_written_off CHECK (
        (status = 'WRITTEN_OFF') = (written_off_at IS NOT NULL)
        AND (status <> 'WRITTEN_OFF' OR payment_status <> 'PAID'))
);
-- BR-P06, DEC-03 A: tối đa 1 Bill hiện hành (ACTIVE hoặc VOID_PENDING) mỗi Order.
CREATE UNIQUE INDEX ux_bill_current_per_order ON bill (order_id) WHERE status IN ('ACTIVE', 'VOID_PENDING');
CREATE INDEX ix_bill_order ON bill (order_id, created_at);
-- Danh sách "Cần xử lý": Bill đang chờ hoàn tiền.
CREATE INDEX ix_bill_void_pending ON bill (void_requested_at) WHERE status = 'VOID_PENDING';
CREATE INDEX ix_bill_created_at ON bill (created_at);
COMMENT ON TABLE bill IS 'Hóa đơn tạm tính nội bộ (BILL-YYYYMMDD-NNNN). Số liệu là snapshot bất biến (BR-P06); sửa sai bằng Void + Bill thay thế. VOIDED/WRITTEN_OFF là trạng thái cuối.';
COMMENT ON COLUMN bill.payment_status IS 'Suy ra từ net_collected = TPS - TRS so với total_amount (BR-P11); được kiểm tra ở cuối transaction bởi trg_bill_invariants.';
COMMENT ON COLUMN bill.void_type IS 'Phân biệt 3 đường VOIDED: SESSION_REOPEN (BR-P08 a), MANAGER_VOID (BR-P09), FORCE_CLOSE_NO_CHARGE (BR-P15/BR-P18).';

CREATE TABLE payment_transaction (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY,
    bill_id          BIGINT      NOT NULL,
    request_id       UUID        NOT NULL,
    receipt_number   VARCHAR(13),
    method           VARCHAR(16) NOT NULL,
    amount           BIGINT      NOT NULL,
    status           VARCHAR(16) NOT NULL,
    provider         VARCHAR(50),
    provider_txn_id  VARCHAR(100),
    note             TEXT,
    failure_reason   TEXT,
    created_by       BIGINT      NOT NULL,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    confirmed_by     BIGINT,
    confirmed_at     TIMESTAMPTZ,
    CONSTRAINT pk_payment_transaction PRIMARY KEY (id),
    CONSTRAINT fk_payment_transaction_bill FOREIGN KEY (bill_id) REFERENCES bill (id),
    CONSTRAINT fk_payment_transaction_created_by FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT fk_payment_transaction_confirmed_by FOREIGN KEY (confirmed_by) REFERENCES users (id),
    -- NFR-06, §7.7: idempotent theo requestId.
    CONSTRAINT uq_payment_transaction_request UNIQUE (request_id),
    CONSTRAINT uq_payment_transaction_receipt UNIQUE (receipt_number),
    CONSTRAINT ck_payment_transaction_method CHECK (method IN ('CASH', 'BANK_TRANSFER', 'CARD_POS', 'OTHER')),
    CONSTRAINT ck_payment_transaction_status CHECK (status IN ('PENDING', 'SUCCESS', 'FAILED')),
    CONSTRAINT ck_payment_transaction_amount CHECK (amount > 0),
    -- BR-P12: mã phiếu YYYYMMDD-NNNN chỉ khi SUCCESS.
    CONSTRAINT ck_payment_transaction_receipt CHECK ((status = 'SUCCESS') = (receipt_number IS NOT NULL)),
    CONSTRAINT ck_payment_transaction_receipt_format CHECK (receipt_number IS NULL OR receipt_number ~ '^[0-9]{8}-[0-9]{4}$'),
    CONSTRAINT ck_payment_transaction_confirmed CHECK ((status = 'PENDING') = (confirmed_at IS NULL)),
    CONSTRAINT ck_payment_transaction_failure CHECK (
        status <> 'FAILED' OR (failure_reason IS NOT NULL AND length(btrim(failure_reason)) > 0)),
    CONSTRAINT ck_payment_transaction_provider CHECK (provider_txn_id IS NULL OR provider IS NOT NULL)
);
CREATE UNIQUE INDEX ux_payment_transaction_provider_txn ON payment_transaction (provider, provider_txn_id)
    WHERE provider_txn_id IS NOT NULL;
CREATE INDEX ix_payment_transaction_bill ON payment_transaction (bill_id, status);
-- Báo cáo doanh thu theo ngày/ca/phương thức (FR-RPT-01, NFR-01).
CREATE INDEX ix_payment_transaction_revenue ON payment_transaction (confirmed_at) INCLUDE (amount, method, bill_id)
    WHERE status = 'SUCCESS';
COMMENT ON TABLE payment_transaction IS 'Chỉ thu tiền, bất biến (BR-P10): chỉ được chuyển PENDING -> SUCCESS/FAILED một lần; không xóa.';

CREATE TABLE refund_transaction (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY,
    bill_id          BIGINT      NOT NULL,
    request_id       UUID        NOT NULL,
    receipt_number   VARCHAR(16),
    method           VARCHAR(16) NOT NULL,
    amount           BIGINT      NOT NULL,
    status           VARCHAR(16) NOT NULL,
    reason           TEXT        NOT NULL,
    failure_reason   TEXT,
    created_by       BIGINT      NOT NULL,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    confirmed_by     BIGINT,
    confirmed_at     TIMESTAMPTZ,
    CONSTRAINT pk_refund_transaction PRIMARY KEY (id),
    CONSTRAINT fk_refund_transaction_bill FOREIGN KEY (bill_id) REFERENCES bill (id),
    CONSTRAINT fk_refund_transaction_created_by FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT fk_refund_transaction_confirmed_by FOREIGN KEY (confirmed_by) REFERENCES users (id),
    CONSTRAINT uq_refund_transaction_request UNIQUE (request_id),
    CONSTRAINT uq_refund_transaction_receipt UNIQUE (receipt_number),
    CONSTRAINT ck_refund_transaction_method CHECK (method IN ('CASH', 'BANK_TRANSFER', 'CARD_POS', 'OTHER')),
    CONSTRAINT ck_refund_transaction_status CHECK (status IN ('PENDING', 'SUCCESS', 'FAILED')),
    CONSTRAINT ck_refund_transaction_amount CHECK (amount > 0),
    CONSTRAINT ck_refund_transaction_reason CHECK (length(btrim(reason)) > 0),
    -- BR-P12: mã phiếu RF-YYYYMMDD-NNNN chỉ khi SUCCESS.
    CONSTRAINT ck_refund_transaction_receipt CHECK ((status = 'SUCCESS') = (receipt_number IS NOT NULL)),
    CONSTRAINT ck_refund_transaction_receipt_format CHECK (receipt_number IS NULL OR receipt_number ~ '^RF-[0-9]{8}-[0-9]{4}$'),
    CONSTRAINT ck_refund_transaction_confirmed CHECK (
        (status = 'PENDING' AND confirmed_at IS NULL AND confirmed_by IS NULL)
        OR (status <> 'PENDING' AND confirmed_at IS NOT NULL AND confirmed_by IS NOT NULL)),
    CONSTRAINT ck_refund_transaction_failure CHECK (
        status <> 'FAILED' OR (failure_reason IS NOT NULL AND length(btrim(failure_reason)) > 0))
);
CREATE INDEX ix_refund_transaction_bill ON refund_transaction (bill_id, status);
-- Báo cáo Refund và doanh thu ròng (FR-RPT-01/02).
CREATE INDEX ix_refund_transaction_report ON refund_transaction (confirmed_at) INCLUDE (amount, method, bill_id)
    WHERE status = 'SUCCESS';
COMMENT ON TABLE refund_transaction IS 'Chỉ hoàn tiền phục vụ Void (BR-P13). Chỉ Manager (REFUND_RECORD) ghi; SUCCESS chỉ khi tiền thực tế đã hoàn. Bất biến.';

CREATE TABLE transaction_status_history (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY,
    transaction_type        VARCHAR(8)  NOT NULL,
    payment_transaction_id  BIGINT,
    refund_transaction_id   BIGINT,
    from_status             VARCHAR(16),
    to_status               VARCHAR(16) NOT NULL,
    changed_by              BIGINT,
    changed_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    reason                  TEXT,
    CONSTRAINT pk_transaction_status_history PRIMARY KEY (id),
    CONSTRAINT fk_tsh_payment FOREIGN KEY (payment_transaction_id) REFERENCES payment_transaction (id),
    CONSTRAINT fk_tsh_refund FOREIGN KEY (refund_transaction_id) REFERENCES refund_transaction (id),
    CONSTRAINT fk_tsh_changed_by FOREIGN KEY (changed_by) REFERENCES users (id),
    CONSTRAINT ck_tsh_type CHECK (
        (transaction_type = 'PAYMENT' AND payment_transaction_id IS NOT NULL AND refund_transaction_id IS NULL)
        OR (transaction_type = 'REFUND' AND refund_transaction_id IS NOT NULL AND payment_transaction_id IS NULL)),
    CONSTRAINT ck_tsh_from_status CHECK (from_status IS NULL OR from_status = 'PENDING'),
    CONSTRAINT ck_tsh_to_status CHECK (to_status IN ('PENDING', 'SUCCESS', 'FAILED'))
);
CREATE INDEX ix_tsh_payment ON transaction_status_history (payment_transaction_id) WHERE payment_transaction_id IS NOT NULL;
CREATE INDEX ix_tsh_refund ON transaction_status_history (refund_transaction_id) WHERE refund_transaction_id IS NOT NULL;
COMMENT ON TABLE transaction_status_history IS 'Lịch sử trạng thái Payment và Refund (FR-PAY-04, FR-PAY-08). Do trigger ghi tự động; chỉ thêm. Ứng dụng KHÔNG tự insert.';

-- -----------------------------------------------------------------------------
-- 7. Audit (BR-A05, BR-A07, BR-A08)
-- -----------------------------------------------------------------------------

CREATE TABLE audit_log (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY,
    occurred_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    actor_type       VARCHAR(8)   NOT NULL,
    actor_user_id    BIGINT,
    action           VARCHAR(64)  NOT NULL,
    entity_type      VARCHAR(64)  NOT NULL,
    entity_id        BIGINT,
    old_value        JSONB,
    new_value        JSONB,
    reason           TEXT,
    reauthenticated  BOOLEAN      NOT NULL DEFAULT false,
    correlation_id   VARCHAR(64),
    ip_address       INET,
    CONSTRAINT pk_audit_log PRIMARY KEY (id),
    CONSTRAINT fk_audit_log_actor FOREIGN KEY (actor_user_id) REFERENCES users (id),
    CONSTRAINT ck_audit_log_actor CHECK (
        actor_type IN ('USER', 'GUEST', 'SYSTEM') AND ((actor_type = 'USER') = (actor_user_id IS NOT NULL))),
    CONSTRAINT ck_audit_log_action CHECK (action ~ '^[A-Z][A-Z0-9_]{1,63}$'),
    CONSTRAINT ck_audit_log_entity_type CHECK (entity_type ~ '^[a-z][a-z0-9_]{1,63}$'),
    CONSTRAINT ck_audit_log_reauth_actor CHECK (NOT reauthenticated OR actor_type = 'USER'),
    -- BR-A08: thay đổi role bắt buộc xác thực lại và lý do. BR-A05/BR-P07/P09/P14/S06: các thao tác
    -- tài chính nhạy cảm bắt buộc lý do.
    CONSTRAINT ck_audit_log_role_change CHECK (
        action <> 'USER_ROLE_CHANGED' OR (reauthenticated AND reason IS NOT NULL AND length(btrim(reason)) > 0)),
    CONSTRAINT ck_audit_log_reason_required CHECK (
        action NOT IN ('BILL_DISCOUNT_APPLIED', 'BILL_VOID_REQUESTED', 'BILL_VOID_WITHDRAWN',
                       'SESSION_FORCE_CLOSED', 'ORDER_WRITTEN_OFF', 'PERMISSION_GRANTED', 'PERMISSION_REVOKED',
                       'REFUND_CREATED')
        OR (reason IS NOT NULL AND length(btrim(reason)) > 0))
);
CREATE INDEX ix_audit_log_occurred ON audit_log (occurred_at);
CREATE INDEX ix_audit_log_entity ON audit_log (entity_type, entity_id, occurred_at);
CREATE INDEX ix_audit_log_actor ON audit_log (actor_user_id, occurred_at) WHERE actor_user_id IS NOT NULL;
CREATE INDEX ix_audit_log_action ON audit_log (action, occurred_at);
COMMENT ON TABLE audit_log IS 'Nhật ký thao tác nhạy cảm, bất biến, chỉ thêm (BR-A05). Danh mục action xem DATABASE_DESIGN.md.';

-- =============================================================================
-- 8. Trigger bảo vệ máy trạng thái và tiền
-- =============================================================================

-- 8.1 table_session (§9.6, §9.10)
CREATE FUNCTION fn_table_session_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'OPEN' THEN
            RAISE EXCEPTION 'INVALID_INITIAL_STATUS: phiên mới phải OPEN' USING ERRCODE = 'P0001';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status IN ('CLOSED', 'EXPIRED', 'FORCE_CLOSED') THEN
        RAISE EXCEPTION 'SESSION_FINAL_STATE: phiên % đã %', OLD.id, OLD.status USING ERRCODE = 'P0001';
    END IF;
    IF NEW.table_id <> OLD.table_id OR NEW.opened_at <> OLD.opened_at THEN
        RAISE EXCEPTION 'SESSION_IMMUTABLE: không đổi bàn hoặc thời điểm mở' USING ERRCODE = 'P0001';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
           (OLD.status = 'OPEN'    AND NEW.status IN ('BILLING', 'EXPIRED', 'FORCE_CLOSED'))
        OR (OLD.status = 'BILLING' AND NEW.status IN ('OPEN', 'CLOSED', 'FORCE_CLOSED'))) THEN
        RAISE EXCEPTION 'INVALID_SESSION_TRANSITION: % -> %', OLD.status, NEW.status USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_table_session_guard
    BEFORE INSERT OR UPDATE ON table_session
    FOR EACH ROW EXECUTE FUNCTION fn_table_session_guard();

-- 8.2 orders (§9.3, §9.10; WRITTEN_OFF là trạng thái cuối - P-2)
CREATE FUNCTION fn_orders_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'OPEN' THEN
            RAISE EXCEPTION 'INVALID_INITIAL_STATUS: Order mới phải OPEN' USING ERRCODE = 'P0001';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status IN ('VOIDED', 'WRITTEN_OFF') THEN
        RAISE EXCEPTION 'ORDER_FINAL_STATE: Order % đã %', OLD.id, OLD.status USING ERRCODE = 'P0001';
    END IF;
    IF NEW.session_id <> OLD.session_id THEN
        RAISE EXCEPTION 'ORDER_IMMUTABLE: không đổi phiên của Order' USING ERRCODE = 'P0001';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
           (OLD.status = 'OPEN'   AND NEW.status IN ('LOCKED', 'WRITTEN_OFF', 'VOIDED'))
        OR (OLD.status = 'LOCKED' AND NEW.status IN ('OPEN', 'PAID', 'WRITTEN_OFF', 'VOIDED'))
        OR (OLD.status = 'PAID'   AND NEW.status = 'LOCKED')) THEN
        RAISE EXCEPTION 'INVALID_ORDER_TRANSITION: % -> %', OLD.status, NEW.status USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_orders_guard
    BEFORE INSERT OR UPDATE ON orders
    FOR EACH ROW EXECUTE FUNCTION fn_orders_guard();

-- 8.3 order_item (§9.1, BR-O01, BR-O12)
CREATE FUNCTION fn_order_item_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    v_order_status VARCHAR;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status NOT IN ('PENDING', 'CONFIRMED') THEN
            RAISE EXCEPTION 'INVALID_INITIAL_STATUS: món mới phải PENDING hoặc CONFIRMED' USING ERRCODE = 'P0001';
        END IF;
        RETURN NEW;
    END IF;
    -- BR-O01: snapshot tên, giá, nguồn gốc không đổi.
    IF (NEW.order_id, NEW.batch_id, NEW.product_id, NEW.product_name, NEW.unit_price,
        NEW.option_extra_per_unit, NEW.device_id, NEW.created_by_user_id, NEW.created_at)
       IS DISTINCT FROM
       (OLD.order_id, OLD.batch_id, OLD.product_id, OLD.product_name, OLD.unit_price,
        OLD.option_extra_per_unit, OLD.device_id, OLD.created_by_user_id, OLD.created_at) THEN
        RAISE EXCEPTION 'ORDER_ITEM_SNAPSHOT_IMMUTABLE: món %', OLD.id USING ERRCODE = 'P0001';
    END IF;
    IF (NEW.quantity, NEW.note) IS DISTINCT FROM (OLD.quantity, OLD.note)
       AND OLD.status NOT IN ('PENDING', 'CONFIRMED') THEN
        RAISE EXCEPTION 'ORDER_ITEM_NOT_EDITABLE: món % đang %', OLD.id, OLD.status USING ERRCODE = 'P0001';
    END IF;
    IF NEW.status <> OLD.status THEN
        IF NOT (
               (OLD.status = 'PENDING'   AND NEW.status IN ('CONFIRMED', 'REJECTED', 'CANCELLED'))
            OR (OLD.status = 'CONFIRMED' AND NEW.status IN ('PREPARING', 'CANCELLED', 'REJECTED'))
            OR (OLD.status = 'PREPARING' AND NEW.status IN ('READY', 'REJECTED', 'CANCELLED'))
            OR (OLD.status = 'READY'     AND NEW.status IN ('SERVED', 'CANCELLED'))) THEN
            RAISE EXCEPTION 'INVALID_ORDER_ITEM_TRANSITION: % -> %', OLD.status, NEW.status USING ERRCODE = 'P0001';
        END IF;
        -- BR-O06: hủy/từ chối món đã bắt đầu nấu luôn wasted.
        IF NEW.status IN ('CANCELLED', 'REJECTED') AND OLD.status IN ('PREPARING', 'READY') AND NOT NEW.wasted THEN
            RAISE EXCEPTION 'ORDER_ITEM_WASTED_REQUIRED: món % hủy/từ chối khi % phải wasted', OLD.id, OLD.status
                USING ERRCODE = 'P0001';
        END IF;
    END IF;
    -- BR-O12: Order không OPEN thì không hủy/từ chối, không sửa món.
    IF (NEW.status <> OLD.status AND NEW.status IN ('CANCELLED', 'REJECTED'))
       OR (NEW.quantity, NEW.note) IS DISTINCT FROM (OLD.quantity, OLD.note) THEN
        SELECT status INTO v_order_status FROM orders WHERE id = NEW.order_id;
        IF v_order_status <> 'OPEN' THEN
            RAISE EXCEPTION 'ORDER_NOT_OPEN: Order % đang %, không hủy/từ chối/sửa món (BR-O12)',
                NEW.order_id, v_order_status USING ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_order_item_guard
    BEFORE INSERT OR UPDATE ON order_item
    FOR EACH ROW EXECUTE FUNCTION fn_order_item_guard();

-- 8.4 bill: snapshot bất biến, máy trạng thái, mã Bill (BR-P06, BR-P12, BR-P15, §9.10)
CREATE FUNCTION fn_bill_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'ACTIVE' THEN
            RAISE EXCEPTION 'INVALID_INITIAL_STATUS: Bill mới phải ACTIVE' USING ERRCODE = 'P0001';
        END IF;
        -- Ứng dụng có thể tự lấy số bằng fn_next_document_number('BILL'); nếu để NULL thì cấp tại đây.
        IF NEW.bill_number IS NULL THEN
            NEW.bill_number := fn_next_document_number('BILL');
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status IN ('VOIDED', 'WRITTEN_OFF') THEN
        RAISE EXCEPTION 'BILL_FINAL_STATE: Bill % đã %', OLD.bill_number, OLD.status USING ERRCODE = 'P0001';
    END IF;
    IF (NEW.order_id, NEW.bill_number, NEW.subtotal_amount, NEW.discount_amount, NEW.discount_reason,
        NEW.discounted_by, NEW.net_amount, NEW.service_fee_rate, NEW.service_fee_taxable,
        NEW.service_fee_amount, NEW.total_amount, NEW.vat_rate, NEW.vat_amount, NEW.replaces_bill_id,
        NEW.created_by, NEW.created_at)
       IS DISTINCT FROM
       (OLD.order_id, OLD.bill_number, OLD.subtotal_amount, OLD.discount_amount, OLD.discount_reason,
        OLD.discounted_by, OLD.net_amount, OLD.service_fee_rate, OLD.service_fee_taxable,
        OLD.service_fee_amount, OLD.total_amount, OLD.vat_rate, OLD.vat_amount, OLD.replaces_bill_id,
        OLD.created_by, OLD.created_at) THEN
        RAISE EXCEPTION 'BILL_SNAPSHOT_IMMUTABLE: Bill % (BR-P06)', OLD.bill_number USING ERRCODE = 'P0001';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
           (OLD.status = 'ACTIVE'       AND NEW.status IN ('VOID_PENDING', 'VOIDED', 'WRITTEN_OFF'))
        OR (OLD.status = 'VOID_PENDING' AND NEW.status IN ('ACTIVE', 'VOIDED'))) THEN
        RAISE EXCEPTION 'INVALID_BILL_TRANSITION: % -> %', OLD.status, NEW.status USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_bill_guard
    BEFORE INSERT OR UPDATE ON bill
    FOR EACH ROW EXECUTE FUNCTION fn_bill_guard();

-- 8.5 payment_transaction / refund_transaction: bất biến + cấp mã phiếu (BR-P10, BR-P12, BR-P13)
-- Cho phép duy nhất một lần chuyển PENDING -> SUCCESS/FAILED; các cột nghiệp vụ không đổi.
CREATE FUNCTION fn_money_txn_before() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    v_seq_type VARCHAR := CASE TG_TABLE_NAME WHEN 'payment_transaction' THEN 'PAYMENT_RECEIPT' ELSE 'REFUND_RECEIPT' END;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF OLD.status <> 'PENDING' THEN
            RAISE EXCEPTION 'TRANSACTION_IMMUTABLE: giao dịch % đã %', OLD.id, OLD.status USING ERRCODE = 'P0001';
        END IF;
        IF (NEW.bill_id, NEW.request_id, NEW.method, NEW.amount, NEW.created_by, NEW.created_at)
           IS DISTINCT FROM (OLD.bill_id, OLD.request_id, OLD.method, OLD.amount, OLD.created_by, OLD.created_at) THEN
            RAISE EXCEPTION 'TRANSACTION_IMMUTABLE: chỉ được đổi trạng thái của giao dịch %', OLD.id USING ERRCODE = 'P0001';
        END IF;
    END IF;
    -- BR-P12: chỉ cấp mã phiếu khi SUCCESS (ứng dụng có thể tự cấp trước bằng fn_next_document_number).
    IF NEW.status = 'SUCCESS' AND NEW.receipt_number IS NULL THEN
        NEW.receipt_number := fn_next_document_number(v_seq_type);
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_payment_transaction_before
    BEFORE INSERT OR UPDATE ON payment_transaction
    FOR EACH ROW EXECUTE FUNCTION fn_money_txn_before();
CREATE TRIGGER trg_refund_transaction_before
    BEFORE INSERT OR UPDATE ON refund_transaction
    FOR EACH ROW EXECUTE FUNCTION fn_money_txn_before();

-- Kiểm tra giới hạn tiền ngay khi ghi giao dịch. Khóa dòng Bill để tuần tự hóa các giao dịch
-- đồng thời trên cùng Bill (hai lần thu cùng lúc không thể vượt Total).
--   Payment (BR-P10): Bill phải ACTIVE; TPS + TPP - TRS <= Total.
--   Refund  (BR-P13): Bill phải VOID_PENDING (hoặc VOIDED trong cùng transaction hoàn tất Void);
--                     TRS + TRP <= TPS  <=>  mỗi Refund mới <= remaining_refundable.
CREATE FUNCTION fn_money_txn_validate() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    v_bill  bill%ROWTYPE;
    v_tps   BIGINT;
    v_tpp   BIGINT;
    v_trs   BIGINT;
    v_trp   BIGINT;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.status = OLD.status THEN
        RETURN NULL;
    END IF;
    SELECT * INTO v_bill FROM bill WHERE id = NEW.bill_id FOR UPDATE;

    SELECT COALESCE(SUM(amount) FILTER (WHERE status = 'SUCCESS'), 0),
           COALESCE(SUM(amount) FILTER (WHERE status = 'PENDING'), 0)
      INTO v_tps, v_tpp FROM payment_transaction WHERE bill_id = NEW.bill_id;
    SELECT COALESCE(SUM(amount) FILTER (WHERE status = 'SUCCESS'), 0),
           COALESCE(SUM(amount) FILTER (WHERE status = 'PENDING'), 0)
      INTO v_trs, v_trp FROM refund_transaction WHERE bill_id = NEW.bill_id;

    IF TG_TABLE_NAME = 'payment_transaction' THEN
        IF NEW.status IN ('PENDING', 'SUCCESS') AND v_bill.status <> 'ACTIVE' THEN
            RAISE EXCEPTION 'PAYMENT_BILL_NOT_ACTIVE: Bill % đang %', v_bill.bill_number, v_bill.status
                USING ERRCODE = 'P0001';
        END IF;
        IF v_tps + v_tpp - v_trs > v_bill.total_amount THEN
            RAISE EXCEPTION 'PAYMENT_EXCEEDS_REMAINING: Bill % (BR-P10)', v_bill.bill_number USING ERRCODE = 'P0001';
        END IF;
    ELSE
        IF NEW.status IN ('PENDING', 'SUCCESS') AND v_bill.status NOT IN ('VOID_PENDING', 'VOIDED') THEN
            RAISE EXCEPTION 'REFUND_REQUIRES_VOID_PENDING: Bill % đang % (BR-P13)', v_bill.bill_number, v_bill.status
                USING ERRCODE = 'P0001';
        END IF;
        IF v_trs + v_trp > v_tps THEN
            RAISE EXCEPTION 'REFUND_EXCEEDS_REFUNDABLE: Bill % TPS=% TRS=% TRP=% (BR-P13)',
                v_bill.bill_number, v_tps, v_trs, v_trp USING ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;
CREATE TRIGGER trg_payment_transaction_validate
    AFTER INSERT OR UPDATE OF status ON payment_transaction
    FOR EACH ROW EXECUTE FUNCTION fn_money_txn_validate();
CREATE TRIGGER trg_refund_transaction_validate
    AFTER INSERT OR UPDATE OF status ON refund_transaction
    FOR EACH ROW EXECUTE FUNCTION fn_money_txn_validate();

-- Ghi lịch sử trạng thái tự động (transaction_status_history).
CREATE FUNCTION fn_money_txn_history() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    v_is_payment BOOLEAN := TG_TABLE_NAME = 'payment_transaction';
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.status = OLD.status THEN
        RETURN NULL;
    END IF;
    INSERT INTO transaction_status_history (
        transaction_type, payment_transaction_id, refund_transaction_id,
        from_status, to_status, changed_by, changed_at, reason)
    VALUES (
        CASE WHEN v_is_payment THEN 'PAYMENT' ELSE 'REFUND' END,
        CASE WHEN v_is_payment THEN NEW.id END,
        CASE WHEN v_is_payment THEN NULL ELSE NEW.id END,
        CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.status END,
        NEW.status,
        CASE WHEN TG_OP = 'INSERT' THEN NEW.created_by ELSE COALESCE(NEW.confirmed_by, NEW.created_by) END,
        now(),
        CASE WHEN NEW.status = 'FAILED' THEN NEW.failure_reason
             WHEN TG_OP = 'INSERT' AND NOT v_is_payment THEN to_jsonb(NEW) ->> 'reason'
        END);
    RETURN NULL;
END;
$$;
CREATE TRIGGER trg_payment_transaction_history
    AFTER INSERT OR UPDATE OF status ON payment_transaction
    FOR EACH ROW EXECUTE FUNCTION fn_money_txn_history();
CREATE TRIGGER trg_refund_transaction_history
    AFTER INSERT OR UPDATE OF status ON refund_transaction
    FOR EACH ROW EXECUTE FUNCTION fn_money_txn_history();

-- 8.6 Bất biến cấp Bill, kiểm tra ở CUỐI transaction (DEFERRABLE INITIALLY DEFERRED) để ứng dụng
-- được cập nhật Bill và giao dịch theo bất kỳ thứ tự flush nào trong cùng transaction.
--   * payment_status = f(net_collected, total) theo BR-P11.
--   * ACTIVE / WRITTEN_OFF: không có Refund PENDING/SUCCESS (BR-P13 (4)).
--   * VOID_PENDING: không có Payment PENDING (BR-P09).
--   * VOIDED: TRS = TPS, không Refund PENDING, không Payment PENDING (BR-P09, BR-P13 (5)).
--   * WRITTEN_OFF: không Payment PENDING (BR-S06 (v)).
CREATE FUNCTION fn_bill_invariants() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    -- to_jsonb: tránh tham chiếu cột không tồn tại khi hàm dùng chung cho nhiều bảng.
    v_bill_id BIGINT := CASE WHEN TG_TABLE_NAME = 'bill' THEN NEW.id
                             ELSE (to_jsonb(NEW) ->> 'bill_id')::BIGINT END;
    v_bill    bill%ROWTYPE;
    v_tps     BIGINT;
    v_tpp     BIGINT;
    v_trs     BIGINT;
    v_trp     BIGINT;
    v_net     BIGINT;
    v_expect  VARCHAR;
BEGIN
    SELECT * INTO v_bill FROM bill WHERE id = v_bill_id;
    SELECT COALESCE(SUM(amount) FILTER (WHERE status = 'SUCCESS'), 0),
           COALESCE(SUM(amount) FILTER (WHERE status = 'PENDING'), 0)
      INTO v_tps, v_tpp FROM payment_transaction WHERE bill_id = v_bill_id;
    SELECT COALESCE(SUM(amount) FILTER (WHERE status = 'SUCCESS'), 0),
           COALESCE(SUM(amount) FILTER (WHERE status = 'PENDING'), 0)
      INTO v_trs, v_trp FROM refund_transaction WHERE bill_id = v_bill_id;

    v_net := v_tps - v_trs;
    v_expect := CASE WHEN v_net >= v_bill.total_amount THEN 'PAID'
                     WHEN v_net > 0 THEN 'PARTIALLY_PAID'
                     ELSE 'UNPAID' END;
    IF v_bill.payment_status <> v_expect THEN
        RAISE EXCEPTION 'BILL_PAYMENT_STATUS_MISMATCH: Bill % là % nhưng net_collected=% total=% (BR-P11)',
            v_bill.bill_number, v_bill.payment_status, v_net, v_bill.total_amount USING ERRCODE = 'P0001';
    END IF;
    IF v_bill.status IN ('ACTIVE', 'WRITTEN_OFF') AND (v_trs > 0 OR v_trp > 0) THEN
        RAISE EXCEPTION 'REFUND_ONLY_FOR_VOID: Bill % đang % có Refund PENDING/SUCCESS (BR-P13)',
            v_bill.bill_number, v_bill.status USING ERRCODE = 'P0001';
    END IF;
    IF v_bill.status IN ('VOID_PENDING', 'VOIDED', 'WRITTEN_OFF') AND v_tpp > 0 THEN
        RAISE EXCEPTION 'PENDING_PAYMENT_EXISTS: Bill % đang % còn Payment PENDING (BR-P09, BR-S06)',
            v_bill.bill_number, v_bill.status USING ERRCODE = 'P0001';
    END IF;
    IF v_bill.status = 'VOIDED' AND (v_trs <> v_tps OR v_trp > 0) THEN
        RAISE EXCEPTION 'VOID_NOT_COMPLETE: Bill % TPS=% TRS=% TRP=% (BR-P13 (5))',
            v_bill.bill_number, v_tps, v_trs, v_trp USING ERRCODE = 'P0001';
    END IF;
    RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER trg_bill_invariants
    AFTER INSERT OR UPDATE ON bill
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION fn_bill_invariants();
CREATE CONSTRAINT TRIGGER trg_payment_transaction_bill_invariants
    AFTER INSERT OR UPDATE ON payment_transaction
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION fn_bill_invariants();
CREATE CONSTRAINT TRIGGER trg_refund_transaction_bill_invariants
    AFTER INSERT OR UPDATE ON refund_transaction
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION fn_bill_invariants();

-- 8.7 Append-only và chặn xóa cứng (BR-A03)
CREATE TRIGGER trg_audit_log_append_only
    BEFORE UPDATE OR DELETE ON audit_log
    FOR EACH ROW EXECUTE FUNCTION fn_append_only();
CREATE TRIGGER trg_transaction_status_history_append_only
    BEFORE UPDATE OR DELETE ON transaction_status_history
    FOR EACH ROW EXECUTE FUNCTION fn_append_only();
CREATE TRIGGER trg_order_item_option_append_only
    BEFORE UPDATE OR DELETE ON order_item_option
    FOR EACH ROW EXECUTE FUNCTION fn_append_only();

DO $$
DECLARE
    t TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY[
        'users', 'user_permission', 'restaurant_settings', 'daily_sequence',
        'category', 'product', 'option_group', 'option_item',
        'dining_table', 'qr_code', 'table_session', 'session_device', 'service_call',
        'orders', 'order_batch', 'order_item', 'item_cancel_request',
        'bill', 'payment_transaction', 'refund_transaction']
    LOOP
        EXECUTE format('CREATE TRIGGER trg_%1$s_no_delete BEFORE DELETE ON %1$I '
                       'FOR EACH ROW EXECUTE FUNCTION fn_forbid_delete()', t);
    END LOOP;
END;
$$;
